import pytest

from string_utils import truncate_with_ellipsis


def test_truncate_with_ellipsis_empty_text_zero_max_len():
    assert truncate_with_ellipsis("", 0) == ""


def test_truncate_with_ellipsis_ellipses_not_appended_when_max_len_too_small():
    assert truncate_with_ellipsis("a", 1) == "a"  # max_len <= 3 → hard cut, no ellipsis


def test_truncate_with_ellipsis_ellipses_not_appended_when_max_len_is_3():
    assert truncate_with_ellipsis("abc", 3) == "abc"  # exact fit, no ellipsis


